<?php
require_once __DIR__.'/../lib/bootstrap.php'; require_role('teacher','admin');
$uid=(int)current_user()['id'];$eid=get_int('exam_id');$admin=current_user()['role']==='admin';$owner=$admin?'':' AND e.created_by=?';
$params=$admin?[$eid]:[$eid,$uid];$s=db()->prepare("SELECT e.*,s.title subject_title,c.title class_title FROM exams e JOIN subjects s ON s.id=e.subject_id JOIN classes c ON c.id=e.class_id WHERE e.id=?$owner");$s->execute($params);$exam=$s->fetch();if(!$exam)exit('آزمون پیدا نشد یا دسترسی ندارید.');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$attemptId=(int)($_POST['attempt_id']??0);$s=db()->prepare('SELECT a.*,u.full_name FROM attempts a JOIN users u ON u.id=a.student_id WHERE a.id=? AND a.exam_id=?');$s->execute([$attemptId,$eid]);$attempt=$s->fetch();if(!$attempt){flash('error','تلاش پیدا نشد.');}else{$pdo=db();$pdo->beginTransaction();try{$pdo->prepare('UPDATE attempts SET revoked_at=?,revoked_by=? WHERE id=? AND exam_id=? AND revoked_at IS NULL')->execute([date('Y-m-d H:i:s'),$uid,$attemptId,$eid]);audit('revoke','attempt',$attemptId);$pdo->commit();flash('success','تلاش دانش‌آموز بازنشانی شد و سابقهٔ آن حفظ گردید.');}catch(Throwable $e){$pdo->rollBack();flash('error','بازنشانی تلاش انجام نشد.');}}redirect('teacher/attempts.php?exam_id='.$eid);}
$s=db()->prepare('SELECT a.*,u.full_name,u.mobile FROM attempts a JOIN users u ON u.id=a.student_id WHERE a.exam_id=? ORDER BY u.full_name,a.attempt_no');$s->execute([$eid]);$attempts=$s->fetchAll();$title='مدیریت تلاش‌ها';require __DIR__.'/../partials/header.php';?><div class="card class-toolbar"><div><span class="eyebrow">مدیریت آزمون</span><h1>تلاش‌های دانش‌آموزان</h1><p class="muted"><?=e($exam['title'])?> — <?=e($exam['subject_title'])?> — <?=e($exam['class_title'])?></p></div><a class="btn btn-light" href="<?=e(url('teacher/exams.php?id='.$eid))?>">بازگشت به آزمون</a></div><div class="card"><p class="muted">تلاش بازنشانی‌شده در سابقه باقی می‌ماند، اما سهمیهٔ دانش‌آموز را مصرف نمی‌کند و امکان شرکت مجدد ایجاد می‌شود.</p><table class="table"><thead><tr><th>دانش‌آموز</th><th>تلاش</th><th>شروع</th><th>ثبت</th><th>نمره</th><th>درصد</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody><?php foreach($attempts as $a):$revoked=!empty($a['revoked_at']);?><tr><td><?=e($a['full_name'])?><br><small><?=e($a['mobile'])?></small></td><td><?=e((string)$a['attempt_no'])?> از <?=e((string)($exam['max_attempts']??1))?></td><td><?=e($a['started_at'])?></td><td><?=e($a['submitted_at']??'—')?></td><td><?=format_score($a['score']??0)?> / <?=format_score($exam['total_score'])?></td><td><?=format_score($a['percentage']??0)?>%</td><td><?=e($revoked?'بازنشانی‌شده':$a['status'])?></td><td><?php if(!$revoked):?><a class="btn btn-sm btn-light" href="<?=e(url('student/result.php?id='.$a['id']))?>" target="_blank">کارنامه</a><form method="post" style="display:inline" onsubmit="return confirm('این تلاش بازنشانی شود؟ سابقه حفظ می‌شود اما سهمیه آزاد خواهد شد.')"><?=csrf_field()?><input type="hidden" name="attempt_id" value="<?=$a['id']?>"><button class="btn btn-sm btn-danger">بازنشانی</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php require __DIR__.'/../partials/footer.php'; ?>
